ecc_agent_script_include.script:
ms.include('IllumioHttpIncludes');
ms.include('IllumioMIDConstants');

var IllumioHTTPClient = Class.create();
IllumioHTTPClient.prototype = {
    // jobSysId is optional and carries only the correlation prefix -- the transport does not use
    // it. Without it this client's ~20 log lines (retries, backoff, non-2xx responses) cannot be
    // tied back to the run that produced them, and those are exactly the lines worth finding.
    initialize: function(baseUrl, username, password, protocol, pceMIDProxy, retryParams, jobSysId) {
        this.logger = new IllumioLogUtil(jobSysId, 'IllumioHTTPClient');
        this.baseUrl = baseUrl;
        var proxyFlag = (pceMIDProxy == 'true' || pceMIDProxy == '1' || pceMIDProxy == true || pceMIDProxy == null);
        // we'll skip the logs when creating object for 'snHttpClient'
        var skipLogs = pceMIDProxy == null;
        this.client = this._setupClient(baseUrl, username, password, protocol, proxyFlag, skipLogs);
        retryParams = retryParams || {};
        // Validated, never defaulted. Substituting a default would be this file deciding on the
        // administrator's behalf how hard to hit their PCE, using a number they never entered and
        // cannot see -- and the old behaviour was worse than either: the three values were taken
        // as given, so a configuration saved with 0 (the form's validators permit it) made
        // Math.min(0, 0 + 0) === 0 and every "retry" slept for no time at all. Against a PCE
        // answering 429 that is not a backoff, it is a tight loop that spends the whole retry
        // budget in under a second and guarantees the failure it was meant to prevent.
        //
        // So: all three must be present and greater than zero, or retrying is off entirely. Each
        // one is load-bearing -- a count with no interval retries instantly, an interval with no
        // count never retries, and an increment of zero never grows the wait. A partial
        // configuration is not a weaker retry policy, it is a broken one, and failing the call on
        // the first refusal is the honest outcome. The log line below says which field is at
        // fault, because a silently non-retrying client looks exactly like a flaky PCE.
        this.httpRetryCount = parseInt(retryParams.http_retry_count, 10);
        this.httpRetryIntervalIncrement = parseInt(retryParams.http_retry_interval_increment, 10);
        this.httpRetryIntervalMax = parseInt(retryParams.http_retry_interval_max, 10);

        this.retryEnabled = this._validateRetryParams(skipLogs);

        // Proactive pacing, applied to the PCE client only. Reactive backoff alone cannot stop a
        // 429 -- by the time it fires the PCE has already refused the call, and every refusal is
        // an error line in the log even when the retry succeeds. The label-creation loop POSTs
        // /labels/ back to back, which is what earned the 429s. The SNOW client is the one built
        // with pceMIDProxy omitted -- the same discriminator `skipLogs` already uses above -- and
        // is not throttled: it talks to the instance, which is not rate limited this way, and
        // pacing it would slow every job for nothing.
        this.minCallIntervalMs = skipLogs ? 0 : MIN_PCE_CALL_INTERVAL_MS;
        this.lastCallFinishedAt = 0;
    },

    /**
     * Are all three retry settings a usable retry policy?
     *
     * All or nothing. Every one of the three must parse as a number greater than zero; any that
     * does not disables retrying for this client entirely rather than being replaced.
     *
     * @param {Boolean} skipLogs Suppress the warning, for the instance-facing client
     * @returns {Boolean} true when retrying is safe to attempt
     */
    _validateRetryParams: function(skipLogs) {
        var invalid = [];

        if (isNaN(this.httpRetryCount) || this.httpRetryCount <= 0) {
            invalid.push('Retry Count (' + this.httpRetryCount + ')');
        }
        if (isNaN(this.httpRetryIntervalIncrement) || this.httpRetryIntervalIncrement <= 0) {
            invalid.push('Retry Interval Increment (' + this.httpRetryIntervalIncrement + ')');
        }
        if (isNaN(this.httpRetryIntervalMax) || this.httpRetryIntervalMax <= 0) {
            invalid.push('Retry Interval Max (' + this.httpRetryIntervalMax + ')');
        }

        if (invalid.length === 0) {
            return true;
        }

        if (!skipLogs) {
            this.logger._warning('Retrying is DISABLED for this PCE Configuration: ' +
                invalid.join(', ') + ' must each be greater than zero. Requests that fail with a ' +
                '429 or a 5xx will be reported as failures on the first attempt rather than ' +
                'retried. Correct these on the PCE Configuration record to enable retrying.');
        }

        return false;
    },

    /**
     * Wait, if needed, so consecutive calls to the PCE are never closer than minCallIntervalMs.
     *
     * Costs nothing when the caller is already slower than the interval, which is the normal
     * case -- it only bites on tight loops like label creation.
     */
    _pace: function() {
        if (this.minCallIntervalMs <= 0 || this.lastCallFinishedAt === 0) {
            return;
        }

        var waitMs = this.minCallIntervalMs - (new Date().getTime() - this.lastCallFinishedAt);
        if (waitMs > 0) {
            Packages.java.lang.Thread.sleep(waitMs);
        }
    },

    /**
     * Setup the HTTP client
     * @param {string} baseUrl Base URL of the REST API
     * @param {string} username Username for the REST API
     * @param {string} password Password for the REST API
     * @param {string} protocol Protocol to use for the REST API
     * @param {boolean} proxyFlag Flag to indicate if the proxy should be used
     * @returns {HttpClient} HTTP client
     **/
    _setupClient: function(baseUrl, username, password, protocol, proxyFlag, skipLogs) {
        var client = new HttpClient();
        var authScope = new AuthScope(baseUrl, protocol);
        var credentials = new UsernamePasswordCredentials(username, password);
        client.getParams().setAuthenticationPreemptive(true);
        client.getState().setCredentials(authScope.ANY, credentials);
        var proxy = this._getProxy(proxyFlag, skipLogs);
        if (proxy != null) {
            client.getHostConfiguration().setProxy(proxy.host, proxy.port);
            client.getParams().setAuthenticationPreemptive(true);
            if (proxy.username != null && proxy.password != null) {
                // set the authentication only when username & password aren't null
                client.getState().setProxyCredentials(new AuthScope(proxy.host, proxy.port), new UsernamePasswordCredentials(proxy.username, proxy.password));
            }
        }
        return client;
    },

    /**
     * Get the proxy details
     * @param {boolean} proxyFlag Flag to indicate if the proxy should be used
     * @param {boolean} skipLogs Flag to skip duplicate logs on creation of HTTPClient
     * @returns {object} Proxy details
     **/
    _getProxy: function(proxyFlag, skipLogs) {
        var proxy = null;
        if (ms.getConfigParameter('mid.proxy.use_proxy') != 'true' && proxyFlag) {
            if (!skipLogs) {
                this.logger._warning('Proxy is not configured on MID Server and enabled for connecting to PCE. Please either configure Proxy in MID Server or uncheck the "Enable Proxy between PCE and MID server" checkbox in configuration.');
            }
            return proxy; // null
        } else if (ms.getConfigParameter('mid.proxy.use_proxy') != 'true' && !proxyFlag) {
            if (!skipLogs) {
                this.logger._debug('Proxy is not configured on MID Server and disabled for connecting to PCE. Continuing without proxy to connect with PCE and ServiceNow instance.');
            }
            return proxy; // null
        } else if (ms.getConfigParameter('mid.proxy.use_proxy') == 'true' && proxyFlag) {
            if (!skipLogs) {
                this.logger._debug('Proxy is configured on MID Server and enabled for connecting to PCE. Proceeding to use proxy to connect with PCE and ServiceNow instance.');
            }
            var proxyHost = ms.getConfigParameter('mid.proxy.host');
            var proxyPort = ms.getConfigParameter('mid.proxy.port');
            var proxyUsername = ms.getConfigParameter('mid.proxy.username');
            var proxyPassword = ms.getConfigParameter('mid.proxy.password');
            proxy = {
                host: proxyHost,
                port: proxyPort,
                username: proxyUsername,
                password: proxyPassword
            };
            return proxy; // non-null
        } else if (ms.getConfigParameter('mid.proxy.use_proxy') == 'true' && !proxyFlag) {
            if (!skipLogs) {
                this.logger._debug('Proxy is configured on MID Server and disabled for connecting to PCE. Proceeding to use proxy for ServiceNow instance but not for PCE.');
            }
            return proxy; // null
        } else {
            if (!skipLogs) {
                this.logger._error('Found an invalid scenario with MID Server proxy value (' + ms.getConfigParameter('mid.proxy.use_proxy') + ') and the checkbox. Please recheck the setup or reach out to Illumio Support.');
            }
            // just in case if we ever fall into gaps due to misconfiguration
            return null;
        }
    },

    /**
     * Execute the HTTP request
     * @param {String} endpoint Endpoint of the API
     * @param {String} queryString Query to add in the URL
     * @param {String} methodName Name of the method
     * @param {JSON} headers Object of headers to add to the request
     * @param {JSON} requestData Request body as JSON
     * @returns {JSON} Object of the response
     */
    _executeMethod: function(endpoint, queryString, method, headers, requestData, retryCount, lastSleepTime) {
        this.logger._debug('APICALL: ' + method.getName() + ' endpoint: ' + endpoint + ' queryString: ' + queryString);
        if (queryString != '') {
            method.setQueryString(queryString);
        }

        if (headers) {
            for (var header in headers) {
                method.addRequestHeader(header, headers[header]);
            }
        }
        if (requestData) {
            method.setRequestBody(JSON.stringify(requestData));
            method.addRequestHeader('Content-Type', 'application/json; charset=utf-8');
        }

        try {
            this._pace();
            this.client.executeMethod(method);
            this.lastCallFinishedAt = new Date().getTime();
            var responseBody = method.getResponseBody();

            if (responseBody)
                responseBody = IOUtils.toString(responseBody, "UTF-8");
            else
                responseBody = method.getResponseBodyAsString();

            var responseCode = parseInt(method.getStatusCode());
            var getMethodResponseHeaders = method.getResponseHeaders();
            var responseHeaders = {};
            for (var i = 0, len = getMethodResponseHeaders.length; i < len; i++) {
                responseHeaders[getMethodResponseHeaders[i].getName()] = getMethodResponseHeaders[i].getValue();
            }

            // if response status is 200 ok or 202 for async request
            if (responseCode >= 200 && responseCode < 300) {
                var responseObj = {
                    hasError: false,
                    data: responseBody ? JSON.parse(responseBody) : new JSON().decode(responseBody),
                    headers: responseHeaders,
                    status: responseCode
                };
                this.logger._debug('HTTP ' + method.getName() + ' Call complete, status: ' + responseCode);
                return responseObj;
            }

            retryCount = (typeof retryCount == 'undefined') ? this.httpRetryCount : retryCount;
            // retryEnabled first: with an incomplete retry configuration there is no safe wait to
            // compute, so the call fails here on its first refusal instead of being retried with
            // a number this file invented. The constructor has already said so in the agent log.
            if (!this.retryEnabled || retryCount <= 0 ||
                (RETRY_CODES.indexOf(responseCode) == -1 && responseCode < 500)) {
                this.logger._error('Failed: HTTP' + method.getName() + ' Call, status: ' + responseCode);
                this.logger._debug("Failure reason: " + method.getResponseBodyAsString());
                if (!this.retryEnabled && (RETRY_CODES.indexOf(responseCode) != -1 ||
                        responseCode >= 500)) {
                    // Name it at the point of loss. Otherwise a 429 that would have succeeded on
                    // the second attempt is indistinguishable from a PCE that is simply down.
                    this.logger._error('This status was retryable, but retrying is disabled ' +
                        'because the PCE Configuration\'s Retry Count, Retry Interval Increment ' +
                        'and Retry Interval Max are not all greater than zero.');
                }
                return {
                    hasError: true,
                    status: responseCode
                };
            }

            lastSleepTime = lastSleepTime ? lastSleepTime : 0;
            lastSleepTime = Math.min(this.httpRetryIntervalMax, lastSleepTime + this.httpRetryIntervalIncrement);

            // Retry-After is the PCE telling us exactly how long it wants; prefer it over the
            // ramp. Only when it is present and parses -- parseRetryAfterHeader returns 0 for a
            // header it cannot read, and 0 means "do not use it", not "retry immediately".
            var retryAfterSeconds = 0;
            if (responseCode == 429) {
                var retryAfterHeader = this._findHeader(responseHeaders, 'retry-after');
                if (retryAfterHeader) {
                    retryAfterSeconds = this.parseRetryAfterHeader(retryAfterHeader);
                }
            }
            if (retryAfterSeconds > 0) {
                lastSleepTime = Math.min(retryAfterSeconds, this.httpRetryIntervalMax);
            }

            // No floor is applied here, and none is needed. Reaching this line means
            // retryEnabled, which means all three settings parsed as integers greater than zero,
            // which makes Math.min(max, ramp) and a positive Retry-After both at least 1. The
            // "Waiting for 0 seconds" this used to print was the unvalidated configuration
            // showing through, not arithmetic that needs guarding.
            this.logger._warning('HTTP ' + method.getName() + ' ' + endpoint + ' returned ' +
                responseCode + '. Waiting ' + lastSleepTime + ' seconds before retrying (' +
                retryCount + ' attempt(s) left).');
            method.releaseConnection();
            Packages.java.lang.Thread.sleep(lastSleepTime * 1000);
            return this._executeMethod(endpoint, queryString, method, headers, requestData, retryCount - 1, lastSleepTime);
        } catch (e) {
            this.logger._error('PCE request failed : Exception ' + e);
            this.logger._error('Failed: HTTP' + method.getName() + ' Call, status: 0');
            return {
                hasError: true,
                status: 0
            };
        } finally {
            method.releaseConnection();
        }
    },

    /**
     * Execute the GET call and retry multiple times if the request fails
     * @param {String} endpoint Endpoint of the API
     * @param {String} queryString Query to add in the URL
     * @param {JSON} headers Object of headers to add to the request
     * @param {JSON} requestData Request body as JSON
     * @returns {JSON} Object of the response
     **/
    get: function(endpoint, queryString, headers, requestData) {
        var getMethod = new GetMethod(this.baseUrl + endpoint);
        return this._executeMethod(endpoint, queryString, getMethod, headers, requestData);
    },

    /**
     * Execute the POST call and retry multiple times if the request fails
     * @param {String} endpoint Endpoint of the API
     * @param {String} queryString Query to add in the URL
     * @param {JSON} headers Object of headers to add to the request
     * @param {JSON} requestData Request body as JSON
     * @returns {JSON} Object of the response
     **/
    post: function(endpoint, queryString, headers, requestData) {
        var postMethod = new PostMethod(this.baseUrl + endpoint);
        return this._executeMethod(endpoint, queryString, postMethod, headers, requestData);
    },

    /**
     * Execute the PUT call and retry multiple times if the request fails
     * @param {String} endpoint Endpoint of the API
     * @param {String} queryString Query to add in the URL
     * @param {JSON} headers Object of headers to add to the request
     * @param {JSON} requestData Request body as JSON
     * @returns {JSON} Object of the response
     **/
    put: function(endpoint, queryString, headers, requestData) {
        var putMethod = new PutMethod(this.baseUrl + endpoint);
        return this._executeMethod(endpoint, queryString, putMethod, headers, requestData);
    },

    /**
     * Execute the DELETE call and retry multiple times if the request fails
     * @param {String} endpoint Endpoint of the API
     * @param {String} queryString Query to add in the URL
     * @param {JSON} headers Object of headers to add to the request
     * @param {JSON} requestData Request body as JSON
     * @returns {JSON} Object of the response
     **/
    deleteMethod: function(endpoint, queryString, headers, requestData) {
        var method = new DeleteMethod(this.baseUrl + endpoint);
        return this._executeMethod(endpoint, queryString, method, headers, requestData);
    },

    /**
     * POST a file from disk as the raw request body.
     *
     * Deliberately not routed through _executeMethod. That one serialises the body with
     * JSON.stringify, which would read the whole file into memory as a string and defeat the
     * point of assembling it on disk; FileRequestEntity streams it instead, so a 120 MB preview
     * costs the same memory as a 1 KB one.
     *
     * Also deliberately NOT retried. _executeMethod retries on 5xx, which is right for an
     * idempotent call and wrong here -- a request that timed out after the instance stored the
     * attachment would leave a second copy on the record, and a duplicate preview is worse than a
     * failed one because nothing marks which is current. The caller fails the job instead.
     *
     * @param {String} endpoint Endpoint of the API
     * @param {String} queryString Query to add in the URL
     * @param {java.io.File} file File to send as the body
     * @param {String} contentType Content type of the body
     * @returns {JSON} Object of the response
     **/
    postFile: function(endpoint, queryString, file, contentType) {
        var postMethod = new PostMethod(this.baseUrl + endpoint);
        if (queryString) {
            postMethod.setQueryString(queryString);
        }

        try {
            postMethod.setRequestEntity(new FileRequestEntity(file, contentType));
            this.client.executeMethod(postMethod);

            var responseCode = parseInt(postMethod.getStatusCode());
            var responseBody = postMethod.getResponseBodyAsString();

            if (responseCode < 200 || responseCode >= 300) {
                this.logger._error('Failed: HTTP POST file call, status: ' + responseCode);
                this.logger._debug('Failure reason: ' + responseBody);
                return {
                    hasError: true,
                    status: responseCode
                };
            }

            var data = null;
            try {
                data = responseBody ? JSON.parse(responseBody) : null;
            } catch (parseException) {
                // A 2xx with an unreadable body still means the file landed. Only the caller's
                // logging wants the body, so this is not an error.
                this.logger._debug('POST file succeeded with an unparseable body: ' + responseBody);
            }

            this.logger._debug('HTTP POST file call complete, status: ' + responseCode);
            return {
                hasError: false,
                data: data,
                status: responseCode
            };
        } catch (e) {
            this.logger._error('POST file request failed : Exception ' + e);
            return {
                hasError: true,
                status: 0
            };
        } finally {
            postMethod.releaseConnection();
        }
    },

    /**
     * Get the value of the parameter from the config file
     * @param {string} parm parameters to get from config.xml
     * @returns Value of the parameter
     */
    getMidConfigParam: function(parm) {
        try {
            var m = Packages.com.service_now.mid.MIDServer.get();
            var config = m.getConfig();
            var result = config.getParameter(parm);
            var result_alternative = config.getProperty(parm);

            if (result) {
                return result;
            } else if (result_alternative) {
                return result_alternative;
            } else {
                config = Packages.com.service_now.mid.services.Config.get();
                result = config.getProperty(parm);
                return result;
            }
        } catch (error) {
            this.logger._except('Failed to load mid server configurations.');
            return null;
        }
    },

    /**
     * Look a response header up without caring about its case.
     *
     * responseHeaders is keyed by whatever casing the server sent, so the direct
     * responseHeaders['retry-after'] lookup this replaces missed every PCE that answers with the
     * conventional "Retry-After" -- the header was read as absent and the ramp used instead.
     *
     * @param {JSON} headers Response headers keyed as received
     * @param {String} name Header name to find, lower case
     * @returns {String} Header value, or '' when not present
     */
    _findHeader: function(headers, name) {
        for (var key in headers) {
            if (('' + key).toLowerCase() === name) {
                return headers[key];
            }
        }
        return '';
    },

    parseRetryAfterHeader: function(retryAfter) {
        var retryAfterSeconds = parseInt(retryAfter);
        if (isNaN(retryAfterSeconds)) {
            var retryAfterDate = new Date(retryAfter);
            if (retryAfterDate) {
                retryAfterSeconds = Math.floor((retryAfterDate.getTime() - new Date().getTime()) / 1000);
            }
        }
        return retryAfterSeconds || 0;
    },

    type: 'IllumioHTTPClient'
};
